import json
import requests
import chardet
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    content = response.content
    if not content:
        return {}
    encoding = from_encoding
    if encoding is None:
        detection = chardet.detect(content)
        encoding = detection.get("encoding")
    if not encoding:
        raise ValueError("Unable to detect encoding for non-empty content")
    text = content.decode(encoding, errors="strict")
    reencoded_bytes = text.encode(to_encoding, errors="strict")
    final_text = reencoded_bytes.decode(to_encoding, errors="strict")
    return json.loads(final_text)

import json
import requests
import chardet
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    content_bytes = response.content
    if not content_bytes:
        return {}
    encoding = from_encoding
    if encoding is None:
        if response.encoding:
            encoding = response.encoding
        else:
            detected = chardet.detect(content_bytes)
            encoding = detected.get("encoding")
    if not encoding:
        raise ValueError("Unable to detect encoding for non-empty content")
    text = content_bytes.decode(encoding, errors="strict")
    normalized_bytes = text.encode(to_encoding, errors="strict")
    normalized_text = normalized_bytes.decode(to_encoding, errors="strict")
    data = json.loads(normalized_text)
    return data

