import json
import requests
def task_func(user, API_URL = 'https://api.github.com/users/'):
    url = f"{API_URL}{user}/repos"
    response = requests.get(url)
    try:
        repos = json.loads(response.text)
    except json.JSONDecodeError:
        return []
    if not isinstance(repos, list):
        return []
    repo_info = []
    for repo in repos:
        name = repo.get("name")
        created_at = repo.get("created_at")
        if name is not None and created_at is not None:
            repo_info.append((created_at, name))
    repo_info.sort(key=lambda x: x[0])
    return [name for _, name in repo_info]

import json
from datetime import datetime
def task_func(json_data):
    try:
        data = json.loads(json_data)
        utc_str = data.get('utc_datetime')
        if not utc_str:
            return False
        if utc_str.endswith('Z'):
            utc_str = utc_str[:-1]
        dt = datetime.fromisoformat(utc_str)
    except (json.JSONDecodeError, ValueError, TypeError):
        return False
    return dt.weekday() >= 5

