import json
def task_func():
    class JSONPostHandler(http.server.BaseHTTPRequestHandler):
        def _send_json_response(self, status_code, payload):
            self.send_response(status_code)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps(payload).encode('utf-8'))

        def do_POST(self):
            content_type = self.headers.get('Content-Type', '')
            if content_type != 'application/json':
                self._send_json_response(
                    400,
                    {"status": "error", "message": "Content-Type header is not application/json"}
                )
                return
            length = self.headers.get('Content-Length')
            try:
                length = int(length) if length is not None else 0
            except ValueError:
                length = 0
            body = self.rfile.read(length).decode('utf-8')
            try:
                data = json.loads(body) if body else {}
            except json.JSONDecodeError:
                self._send_json_response(
                    400,
                    {"status": "error", "message": "No data received"}
                )
                return
            if 'data' not in data:
                self._send_json_response(
                    400,
                    {"status": "error", "message": "No data received"}
                )
                return
            self._send_json_response(
                200,
                {"status": "success", "message": "Data received successfully."}
            )
    return JSONPostHandler

import cgi
import http.server
import json
SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}
ERROR_RESPONSE = {
    'status': 'error',
    'message': 'Invalid data received.'
}
def task_func():
    class PostRequestHandler(http.server.BaseHTTPRequestHandler):
        def _send_response(self, code, body_dict):
            body = json.dumps(body_dict).encode('utf-8')
            self.send_response(code)
            self.send_header('Content-Type', 'application/json')
            self.send_header('Content-Length', str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def do_POST(self):
            content_type = self.headers.get('Content-Type')
            if content_type != 'application/json':
                error_body = {
                    'status': 'error',
                    'message': 'Content-Type header is not application/json'
                }
                self._send_response(400, error_body)
                return
            length_header = self.headers.get('Content-Length')
            try:
                content_length = int(length_header) if length_header is not None else 0
            except ValueError:
                content_length = 0
            body_bytes = self.rfile.read(content_length)
            try:
                data = json.loads(body_bytes.decode('utf-8') or '{}')
            except json.JSONDecodeError:
                error_body = {
                    'status': 'error',
                    'message': 'Invalid JSON'
                }
                self._send_response(400, error_body)
                return
            if 'data' not in data:
                error_body = {
                    'status': 'error',
                    'message': 'No data key in request'
                }
                self._send_response(400, error_body)
                return
            self._send_response(200, SUCCESS_RESPONSE)

    return PostRequestHandler

import collections
import json
import os
def task_func(directory_path: str) -> dict:
    key_counter = collections.Counter()
    for filename in os.listdir(directory_path):
        if filename.endswith(".json"):
            file_path = os.path.join(directory_path, filename)
            try:
                with open(file_path, "r") as f:
                    data = json.load(f)
