import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):
    if not os.path.exists(file_path):
        raise ValueError("File does not exist")
    with open(file_path, "r") as f:
        data = json.load(f)
    required_fields = INPUT_JSON.get("required", [])
    for field in required_fields:
        if field not in data:
            raise ValueError(f"Missing required field: {field}")
    properties = INPUT_JSON.get("properties", {})
    for field, rules in properties.items():
        if field in data:
            expected_type = rules.get("type")
            if expected_type and not isinstance(data[field], expected_type):
                raise ValueError(f"Field '{field}' has incorrect type")
    email_value = data.get("email")
    if email_value is None or not isinstance(email_value, str) or not re.fullmatch(EMAIL_REGEX, email_value):
        raise ValueError("Invalid email format")
    if attribute not in data:
        raise ValueError(f"Attribute '{attribute}' not found")
    return data[attribute]

