import re
import pandas as pd
def task_func(json_str):
    if not json_str or not json_str.strip():
        return pd.DataFrame()
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return pd.DataFrame()
    if not isinstance(data, dict):
        return pd.DataFrame()
    def double_number_value(v):
        if isinstance(v, (int, float)):
            return float(v) * 2
        return v
    def process_list(lst):
        new_list = []
        for item in lst:
            if isinstance(item, (int, float)):
                new_list.append(float(item) * 2)
            else:
                try:
                    num = float(item)
                    new_list.append(num * 2)
                except (TypeError, ValueError):
                    new_list.append(item)
        return new_list
    def process_string(s):
        def repl(match):
            num_str = match.group(0)
            try:
                num = float(num_str)
                doubled = num * 2
                if '.' in num_str or 'e' in num_str.lower() or 'E' in num_str:
                    return str(doubled)
                if doubled.is_integer():
                    return str(int(doubled))
                return str(doubled)
            except ValueError:
                return num_str
        return re.sub(r'-?\d+(\.\d+)?', repl, s)
    normalized = {}
    for k, v in data.items():
        if isinstance(v, dict):
            continue
        if isinstance(v, (int, float)):
            normalized[k] = double_number_value(v)
        elif isinstance(v, list):
            normalized[k] = process_list(v)
        elif isinstance(v, str):
            normalized[k] = process_string(v)
        else:
            normalized[k] = v
    if not normalized:
        return pd.DataFrame()
    df_input = {}
    for k, v in normalized.items():
        if isinstance(v, list):
            df_input[k] = v
        else:
            df_input[k] = [v]
    df = pd.DataFrame(df_input)
    for col in df.columns:
        df[col] = pd.to_numeric(df[col], errors='ignore')
    return df

