import pandas as pd
import json
import numpy as np
import matplotlib.pyplot as plt
COLUMNS = ['email', 'list']
def task_func(json_file):
    with open(json_file, 'r') as f:
        data = json.load(f)
    if isinstance(data, dict):
        if 'email' in data and 'list' in data:
            records = [data]
        else:
            records = data.get('data', [])
    else:
        records = data
    valid_records = []
    for item in records:
        if isinstance(item, dict) and 'email' in item and 'list' in item:
            valid_records.append({'email': item['email'], 'list': item['list']})
    if not valid_records:
        df_empty = pd.DataFrame(columns=['email', 'list', 'sum', 'mean'])
        return df_empty, None
    df = pd.DataFrame(valid_records, columns=COLUMNS)
    def compute_sum(lst):
        if not isinstance(lst, (list, tuple)):
            return np.nan
        arr = []
        for v in lst:
            try:
                arr.append(float(v))
            except (ValueError, TypeError):
                continue
        if not arr:
            return np.nan
        return np.sum(arr)
    def compute_mean(lst):
        if not isinstance(lst, (list, tuple)):
            return np.nan
        arr = []
        for v in lst:
            try:
                arr.append(float(v))
            except (ValueError, TypeError):
                continue
        if not arr:
            return np.nan
        return np.mean(arr)
    df['sum'] = df['list'].apply(compute_sum)
    df['mean'] = df['list'].apply(compute_mean)
    if df.empty:
        return df, None
    fig, ax = plt.subplots()
    x = np.arange(len(df))
    width = 0.35
    ax.bar(x - width/2, df['sum'], width, label='sum')
    ax.bar(x + width/2, df['mean'], width, label='mean')
    ax.set_xticks(x)
    ax.set_xticklabels(df['email'], rotation=45, ha='right')
    ax.legend()
    fig.tight_layout()
    return df, ax

