import json
import re
from collections import Counter
# Constants
REPLACE_NONE = "None"
def task_func(json_str):
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        data = None

    email_pattern = re.compile(r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}')
    collected_values = []

    def process(obj):
        if isinstance(obj, dict):
            new_dict = {}
            for k, v in obj.items():
                if v is None:
                    continue
                processed_v = process(v)
                if processed_v is not None:
                    new_dict[k] = processed_v
            return new_dict
        elif isinstance(obj, list):
            new_list = []
            for item in obj:
                if item is None:
                    continue
                processed_item = process(item)
                if processed_item is not None:
                    new_list.append(processed_item)
            return new_list
        elif isinstance(obj, str):
            if email_pattern.fullmatch(obj):
                value = REPLACE_NONE
            else:
                value = obj
            collected_values.append(value)
            return value
        else:
            collected_values.append(obj)
            return obj

    processed_data = process(data)
    value_counts = Counter(collected_values)

    return {"data": processed_data, "value_counts": value_counts}

