import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    if isinstance(json_data, str):
        try:
            data = json.loads(json_data)
        except json.JSONDecodeError:
            raise ValueError("Malformed JSON data")
    else:
        data = json_data

    if not data:
        raise ValueError("Empty JSON data")

    if not isinstance(data, (list, tuple)):
        raise ValueError("JSON data must be a list of records")

    countries = []
    populations = []

    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Each record must be a dictionary")
        if "Country" not in item or "Population" not in item:
            raise ValueError("Each record must contain 'Country' and 'Population' keys")

        country = item["Country"]
        population = item["Population"]

        if not isinstance(country, str) or country.strip() == "":
            raise ValueError("Country names must be non-empty strings")

        if not isinstance(population, (int, float)) or math.isnan(float(population)):
            raise ValueError("Population must be numeric")

        if population < 0:
            raise ValueError("Population cannot be negative")

        population_int = math.floor(float(population))

        countries.append(country)
        populations.append(population_int)

    df = pd.DataFrame({"Country": countries, "Population": populations})

    if not isinstance(output_dir, str) or output_dir.strip() == "":
        raise ValueError("Invalid output directory")

    output_dir = os.path.abspath(output_dir)

    try:
        os.makedirs(output_dir, exist_ok=True)
    except OSError:
        raise IOError("Cannot create or access the output directory")

    file_path = os.path.join(output_dir, file_name)

    try:
        df.to_csv(file_path, index=False)
    except OSError:
        raise IOError("Failed to write CSV file")

    return file_path, df

