def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except Exception:
        raise ValueError("Malformed JSON data")

    if not data:
        raise ValueError("Empty JSON data")

    records = []
    if isinstance(data, dict):
        data = [data]

    if not isinstance(data, list):
        raise ValueError("JSON data must be a list or dict")

    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Each item must be an object with Country and Population")
        if "Country" not in item or "Population" not in item:
            raise ValueError("Missing Country or Population fields")
        country = item["Country"]
        population = item["Population"]
        if not isinstance(country, str) or not country:
            raise ValueError("Country name must be a non-empty string")
        if not isinstance(population, (int, float)):
            raise ValueError("Population must be numeric")
        if population < 0:
            raise ValueError("Population cannot be negative")
        population_int = int(math.floor(population))
        records.append({"Country": country, "Population": population_int})

    if not records:
        raise ValueError("No valid records found")

    df = pd.DataFrame(records, columns=["Country", "Population"])

    if not os.path.isdir(output_dir):
        try:
            os.makedirs(output_dir, exist_ok=True)
        except Exception as e:
            raise IOError(f"Cannot create directory {output_dir}: {e}")

    file_path = os.path.join(output_dir, file_name)

    try:
        df.to_csv(file_path, index=False)
    except Exception as e:
        raise IOError(f"Failed to write CSV file: {e}")

    return file_path, df

import json
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd
def task_func(json_data: str, key_path: list):
    data = json.loads(json_data)
    current = data
    for key in key_path:
        if isinstance(current, dict) and key in current:
            current = current[key]
        else:
            raise KeyError(f"Key not found in path: {key}")
    values = []
    if isinstance(current, (list, tuple, np.ndarray, pd.Series)):
        for v in current:
            if isinstance(v, (int, float)) and not isinstance(v, bool):
                values.append(v)
    elif isinstance(current, dict):
        for v in current.values():
            if isinstance(v, (int, float)) and not isinstance(v, bool):
                values.append(v)
    elif isinstance(current, pd.DataFrame):
        numeric_df = current.select_dtypes(include=[np.number])
        values = numeric_df.values.flatten().tolist()
    elif isinstance(current, (int, float)) and not isinstance(current, bool):
        values = [current]
    else:
        raise ValueError("No numeric data found at the specified path")
    if not values:
        raise ValueError("No numeric data found at the specified path")
    df = pd.DataFrame({"value": values})
    fig, ax = plt.subplots()
    sns.boxplot(x="value", data=df, ax=ax)
    ax.set_title("Boxplot of Extracted Numeric Data")
    return fig

import json
import os
def task_func(filename, data):
    try:
        with open(filename, "w") as f:
            json.dump(data, f)
    except Exception:
        return False, None
    if not os.path.exists(filename):
        return False, None
    try:
        with open(filename, "r") as f:
            written_data = json.load(f)
    except Exception:
        return False, None
    success = written_data == data
    return success, written_data

