import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    if not isinstance(json_data, str) or not json_data.strip():
        raise ValueError("JSON data is malformed or empty")
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("JSON data is malformed")
    if not isinstance(data, list) or len(data) == 0:
        raise ValueError("JSON data must be a non-empty list")
    countries = []
    populations = []
    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Each item must be a dictionary")
        if "Country" not in item or "Population" not in item:
            raise ValueError("Each item must contain 'Country' and 'Population' keys")
        country = item["Country"]
        population = item["Population"]
        if not isinstance(country, str) or country.strip() == "":
            raise ValueError("Country names must be non-empty strings")
        if isinstance(population, bool):
            raise ValueError("Population must be numeric")
        if not isinstance(population, (int, float)):
            raise ValueError("Population must be numeric")
        if population < 0:
            raise ValueError("Population cannot be negative")
        population_int = math.floor(population)
        countries.append(country)
        populations.append(population_int)
    df = pd.DataFrame({"Country": countries, "Population": populations})
    if not os.path.isdir(output_dir):
        try:
            os.makedirs(output_dir, exist_ok=True)
        except OSError as e:
            raise IOError(f"Cannot create directory: {output_dir}") from e
    file_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(file_path, index=False)
    except OSError as e:
        raise IOError(f"Cannot write file: {file_path}") from e
    return file_path, df

